function resolveWorkspaceSkillSourcePlan(workspaceDir, opts) {
	const selected = process.env.SHIJU_OPENCLAW_SKILL_ROOT;
	if (selected !== undefined) {
		if (selected && (!path.isAbsolute(selected) || !fs.statSync(selected).isDirectory())) throw new Error("Invalid session skill directory");
		const roots = selected ? [{dir: selected, source: "openclaw-extra", tier: "extra"}] : [];
		return {roots, allowSymlinkTargets: selected ? fs.readdirSync(selected).map(name => fs.realpathSync(path.join(selected, name))) : [], pluginSkillRoots: [], managedSkillsDir: selected || path.join(workspaceDir, "skills"), workspaceDir};
	}
